import{_ as l,o as p,c as a,a3 as e}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/07-你属于下流阶层吗？.md","filePath":"books/xialiu-shehui/07-你属于下流阶层吗？.md","lastUpdated":1794732511000}'),t={name:"books/xialiu-shehui/07-你属于下流阶层吗？.md"};function _(o,i,s,r,n,d){return p(),a("div",null,[...i[0]||(i[0]=[e('<h2 id="你属于下流阶层吗" tabindex="-1">你属于下流阶层吗？ <a class="header-anchor" href="#你属于下流阶层吗" aria-label="Permalink to &quot;你属于下流阶层吗？&quot;">​</a></h2><p>首先，让我们来做一个关于“下流指数”的小测试。在以下12个项目中，如果你的实际情况与其中一半以上项目相符合的话，那么，你就已经属于下流阶层的一员了。</p><ol><li><p>年收入不足自己年龄的10倍</p></li><li><p>不考虑将来的事情，快快活活地过好每一天</p></li><li><p>觉得人应该活出自己的色彩</p></li><li><p>期望只做自己喜欢的事情，而不想虚度此生</p></li><li><p>事事嫌麻烦、不修边幅、生活不规整</p></li><li><p>喜欢自己一个人独处</p></li><li><p>生性朴实，不喜欢标显、不出众</p></li><li><p>服饰不追逐流行而是展现自我风格</p></li><li><p>觉得做饭吃饭是一件很麻烦的事情</p></li><li><p>经常吃零食和快餐</p></li><li><p>待在家中玩一整天电脑游戏或上网而不会厌倦</p></li><li><p>未婚（男性33岁以上、女性30岁以上）</p></li></ol><p>下流阶层的出现源于社会的阶层分化。收入的两极分化，导致学习机会以及学习能力的不平等，结果，社会阶层之间的互换流动性越来越差，社会阶层分化形成固定化的倾向，同时不同阶层的“期望差距”也日益扩大，最终作为一个新的社会阶层集团而催生了下流阶层。近年来，学者们在这一领域发表了不少结果类似的研究报告。</p><p>这一倾向充分说明，今天的日本正在从“中流社会”向“下流社会”转变。</p>',5)])])}const u=l(t,[["render",_]]);export{h as __pageData,u as default};
